/** Root of a tree: a leaf carries `value`, a group carries `children`, never both. */
export type Data = { name: string; value?: number; children?: Data[] };

type Circle = d3.HierarchyCircularNode<Data>;
type View = [number, number, number];

const PADDING = 3;
const FONT_SIZE = 11;
/** Mean advance width of 11px sans-serif, used to drop labels wider than their circle. */
const CHAR_WIDTH = 6.2;
const DURATION = 750;

/** The chart paints its own light-on-dark ramp, so label ink is keyed to the mark, not the theme. */
const LEAF_FILL = '#eef4f9';
const INK_ON_DARK = '#e8eef5';
const INK_ON_LIGHT = '#16202c';

export default function ZoomableCirclePacking({
  data = platformTree,
  width
}: {
  data?: Data;
  width: number;
}) {
  // Hooks run before the width===0 guard below, and d3.pack throws on a zero-sized layout.
  const side = Math.max(width, 1);
  const svgRef = useRef<SVGSVGElement>(null);

  const root = useMemo(
    () =>
      d3
        .pack<Data>()
        .size([side, side])
        .padding(PADDING)(
          d3
            .hierarchy(data)
            .sum((d) => d.value ?? 0)
            .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))
        ),
    [data, side]
  );

  const color = useMemo(
    () =>
      d3
        .scaleLinear<string>()
        .domain([0, 4])
        .range(['hsl(222,26%,19%)', 'hsl(196,70%,74%)'])
        .interpolate(d3.interpolateHcl),
    []
  );

  useEffect(() => {
    const element = svgRef.current;
    if (!element) return;

    const svg = d3.select(element);
    svg.selectAll('*').remove();

    // A node's label only ever shows while its parent is the focus, so its rendered
    // radius is known up front; names wider than that are never created.
    const fits = (d: Circle) =>
      d.data.name.length * CHAR_WIDTH < 1.8 * d.r * (side / (2 * (d.parent?.r ?? d.r)));

    svg
      .append('rect')
      .attr('x', -side / 2)
      .attr('y', -side / 2)
      .attr('width', side)
      .attr('height', side)
      .attr('fill', color(0));

    const circles = svg
      .append('g')
      .selectAll<SVGCircleElement, Circle>('circle')
      .data(root.descendants().slice(1))
      .join('circle')
      .attr('fill', (d) => (d.children ? color(d.depth) : LEAF_FILL))
      .attr('stroke-width', 1.5)
      .attr('pointer-events', (d) => (d.children ? null : 'none'));

    const labels = svg
      .append('g')
      .attr('pointer-events', 'none')
      .attr('text-anchor', 'middle')
      .attr('font-size', FONT_SIZE)
      .selectAll<SVGTextElement, Circle>('text')
      .data(root.descendants().slice(1).filter(fits))
      .join('text')
      .attr('fill', (d) => (d.children ? INK_ON_DARK : INK_ON_LIGHT))
      .attr('dy', '0.32em')
      .style('fill-opacity', (d) => (d.parent === root ? 1 : 0))
      .style('display', (d) => (d.parent === root ? 'inline' : 'none'))
      .text((d) => d.data.name);

    let focus: Circle = root;
    let view: View = [root.x, root.y, root.r * 2];

    function zoomTo(next: View) {
      const k = side / next[2];
      view = next;
      const place = (d: Circle) => `translate(${(d.x - next[0]) * k},${(d.y - next[1]) * k})`;
      labels.attr('transform', place);
      circles.attr('transform', place).attr('r', (d) => d.r * k);
    }

    function zoomTowards(target: Circle) {
      focus = target;
      svg.transition().duration(DURATION).tween('zoom', () => {
        const interpolate = d3.interpolateZoom(view, [focus.x, focus.y, focus.r * 2]);
        return (t) => zoomTo(interpolate(t));
      });

      // A sibling transition of equal duration, not an inherited one: @types/d3 cannot
      // express inheriting an SVGSVGElement transition into an SVGTextElement selection.
      labels
        .filter(function (d) {
          return d.parent === focus || this.style.display === 'inline';
        })
        .transition()
        .duration(DURATION)
        .style('fill-opacity', (d) => (d.parent === focus ? 1 : 0))
        .on('start', function (d) {
          if (d.parent === focus) this.style.display = 'inline';
        })
        .on('end', function (d) {
          if (d.parent !== focus) this.style.display = 'none';
        });
    }

    circles
      .on('mouseover', function () {
        d3.select(this).attr('stroke', INK_ON_DARK);
      })
      .on('mouseout', function () {
        d3.select(this).attr('stroke', null);
      })
      .on('click', (event: MouseEvent, d) => {
        if (focus === d) return;
        zoomTowards(d);
        event.stopPropagation();
      });

    svg.on('click', () => {
      if (focus !== root) zoomTowards(root);
    });

    zoomTo(view);

    return () => {
      svg.interrupt();
      svg.selectAll('*').interrupt();
      svg.on('click', null);
      circles.on('mouseover', null).on('mouseout', null).on('click', null);
      svg.selectAll('*').remove();
    };
  }, [root, color, side]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`${-side / 2} ${-side / 2} ${side} ${side}`}
      width="100%"
      height={side}
      role="img"
      aria-label="Zoomable circle packing of a data platform service tree; click a circle to zoom in, the background to zoom out"
      style={{ display: 'block', cursor: 'pointer' }}
    />
  );
}
